void __lib_stable_sort(It first, It last) {
    size_t N = std::distance(first, last);

    // Attempt to allocate auxiliary memory (O(N))
    std::pair<T*, ptrdiff_t> buffer_info = 
        std::get_temporary_buffer<T>(N);

    T* aux_buffer = buffer_info.first;

    if (aux_buffer) {
        // Path A: Optimal Mergesort
        // O(N log N) time, O(N) space.
    } else {
        // Path B: In-place Mergesort (Fallback)
        // Slower: O(N log² N) time, O(1) space.
